C;/summary> public float OutputVoltageSettingFromDevice { get => _outputVoltageSettingFromDevice; set { if (SetProperty(ref _outputVoltageSettingFromDevice, value)) OutputVoltageSetting = value; } } /// &#x3C;summary> /// 输出电流 /// &#x3C;/summary> [ObservableProperty] private string _outputCurrentString = \\\"0.000\\\"; private float _outputCurrent; /// &#x3C;summary> /// 输出电流 /// &#x3C;/summary> public float OutputCurrent { get => _outputCurrent; set { if (SetProperty(ref _outputCurrent, value)) { OutputCurrentString = TotalLimitNum2String(value, 5); OutputCurrentPercentage = OutputCurrent / SettingOcp * 100f; SetEquivalentResistance(); } } } /// &#x3C;summary> /// 设置的输出电流 /// &#x3C;/summary> [ObservableProperty] private float _outputCurrentSetting; private float _outputCurrentSettingFromDevice; /// &#x3C;summary> /// 从设备获取的设置电流 /// &#x3C;/summary> public float OutputCurrentSettingFromDevice { get => _outputCurrentSettingFromDevice; set { if (SetProperty(ref _outputCurrentSettingFromDevice, value)) OutputCurrentSetting = value; } } /// &#x3C;summary> /// 输出功率 /// &#x3C;/summary> [ObservableProperty] private string _outputPowerString = \\\"0.000\\\"; private float _outputPower; /// &#x3C;summary> /// 输出功率 /// &#x3C;/summary> public float OutputPower { get => _outputPower; set { if (SetProperty(ref _outputPower, value)) { OutputPowerString = TotalLimitNum2String(value, 5); OutputPowerPercentage = OutputPower / SettingOpp * 100f; } } } /// &#x3C;summary> /// 输入电压 /// &#x3C;/summary> [ObservableProperty] private string _inputVoltage = \\\"24.0V\\\"; /// &#x3C;summary> /// 内部温度 /// &#x3C;/summary> [ObservableProperty] private string _internalTemperature = \\\"10.0℃\\\"; /// &#x3C;summary> /// 累计电流 /// &#x3C;/summary> [ObservableProperty] private string _totalCurrentCount = \\\"0000.000AH\\\"; /// &#x3C;summary> /// 累计功率 /// &#x3C;/summary> [ObservableProperty] private string _totalPowerCount = \\\"0000.000WH\\\"; /// &#x3C;summary> /// 过压保护显示文本 /// &#x3C;/summary> [ObservableProperty] private string _settingOvpString = \\\"50.00\\\"; private float _settingOvp; /// &#x3C;summary> /// 过压保护 /// &#x3C;/summary> public float SettingOvp { get => _settingOvp; set { if (SetProperty(ref _settingOvp, value)) { SettingOvpString = TotalLimitNum2String(value, 5); OutputVoltagePercentage = OutputVoltage / SettingOvp * 100f; } } } /// &#x3C;summary> /// 过流保护显示文本 /// &#x3C;/summary> [ObservableProperty] private string _settingOcpString = \\\"11.00\\\"; private float _settingOcp; /// &#x3C;summary> /// 过流保护 /// &#x3C;/summary> public float SettingOcp { get => _settingOcp; set { if (SetProperty(ref _settingOcp, value)) { SettingOcpString = TotalLimitNum2String(value, 5); OutputCurrentPercentage = OutputCurrent / SettingOcp * 100f; } } } /// &#x3C;summary> /// 过功率保护 /// &#x3C;/summary> [ObservableProperty] private float _settingOpp = 300; /// &#x3C;summary> /// 当前调节目标是否是C电流 /// &#x3C;/summary> [ObservableProperty] private bool _currentAdjustmentTargetCc; /// &#x3C;summary> /// 是否为CC /// &#x3C;/summary> [ObservableProperty] private bool _useCc; /// &#x3C;summary> /// 是否为输出状态 /// &#x3C;/summary> [ObservableProperty] private bool _outputOn; /// &#x3C;summary> /// 选中的设置组 /// &#x3C;/summary> [ObservableProperty] private byte _selectedSettingGroup; /// &#x3C;summary> /// 站号 /// &#x3C;/summary> [ObservableProperty] private byte _sid; /// &#x3C;summary> /// 设置电压和电流 /// &#x3C;/summary> /// &#x3C;returns>&#x3C;/returns> [RelayCommand] private async Task SetVoltageAndCurrentAsync(CancellationToken ct) { await RT300.SetOutputVoltageSettingAsync(OutputVoltageSetting, ct); await RT300.SetOutputCurrentSettingAsync(OutputCurrentSetting, ct); } /// &#x3C;summary> /// 切换输出状态 /// &#x3C;/summary> /// &#x3C;param name=\\\"ct\\\">&#x3C;/param> /// &#x3C;returns>&#x3C;/returns> [RelayCommand] private async Task SetOutputAsync(CancellationToken ct) { await RT300.SetOutputAsync(!OutputOn, ct); await Task.Delay(200, ct); } private static string TotalLimitNum2String(float num,